R=C=19
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
colored_arms={(3,6):{(2,6),(3,5),(3,7),(4,6)},(4,13):{(3,13),(4,12),(4,14),(5,13)},(12,14):{(11,14),(12,13),(12,15),(13,14)},(14,3):{(13,3),(14,2),(14,4),(15,3)}}
hollow_center=(10,8)
hollow_arms={(9,8),(10,7),(10,9),(11,8)}
all_shapes={k:set(v) for k,v in colored_arms.items()}
for k in centers: all_shapes[k].add(k)
all_shapes[hollow_center]=hollow_arms|{hollow_center}
all_points=set().union(*all_shapes.values())
base=[[0]*C for _ in range(R)]
for (r,c),v in centers.items():base[r][c]=v
for p in set().union(*colored_arms.values())|hollow_arms:base[p[0]][p[1]]=3
# Layers with explicit presence; protect all original marks.
h=[[0]*C for _ in range(R)]; hp=[[False]*C for _ in range(R)]
vv=[[0]*C for _ in range(R)]; vp=[[False]*C for _ in range(R)]
for (r,c),val in centers.items():
 own=all_shapes[(r,c)]
 for dr,dc,layer,pres in [(0,-1,h,hp),(0,1,h,hp),(-1,0,vv,vp),(1,0,vv,vp)]:
  i,j=r+dr,c+dc
  while 0<=i<R and 0<=j<C:
   if (i,j) in all_points and (i,j) not in own: break
   if base[i][j]==0:
    layer[i][j]=val;pres[i][j]=True
   i+=dr;j+=dc
# hollow rays: zero in their orientation layer, entire axis
hr,hc=hollow_center
for j in range(C):
 if base[hr][j]==0: h[hr][j]=0;hp[hr][j]=True
for i in range(R):
 if base[i][hc]==0: vv[i][hc]=0;vp[i][hc]=True
out=[row[:] for row in base]
for i in range(R):
 for j in range(C):
  if base[i][j]==0:
   if vp[i][j]:out[i][j]=vv[i][j]
   elif hp[i][j]:out[i][j]=h[i][j]
for row in out:print('['+','.join(map(str,row))+'],')

